// Si l'app a fourni le Notion page ID directement, on l'utilise
const body = $input.first().json;
const notionId = body.meta?.locataireNotionId || '';

return [{ json: { ...body, _locatairePageId: notionId || null } }];

// Récupère le page ID locataire depuis la branche ID direct ou depuis la recherche Notion
const body = $('Code - Résoudre locataire').first().json;

let locatairePageId = body._locatairePageId;

// Si pas d'ID direct, on le prend depuis le résultat de recherche
if (!locatairePageId) {
  const searchResults = $('Notion - Rechercher locataire').all();
  if (!searchResults || searchResults.length === 0) {
    throw new Error('Locataire introuvable dans Notion : ' + body.meta.locataire);
  }
  locatairePageId = searchResults[0].json.id;
}

return [{ json: { ...body, _locatairePageId: locatairePageId } }];

const payload = $input.first().json;
const { meta, pieces, cles, observations } = payload;

const ETAT_LABELS = { TB: 'Très Bon', B: 'Bon', P: 'Passable', M: 'Mauvais', 'N/A': 'N/A' };

const ROOM_LABELS = {
  entree: 'Entrée', salon: 'Salon / Séjour', cuisine: 'Cuisine',
  wc_communs: 'WC communs', buanderie: 'Buanderie',
  chambre_1: 'Chambre 1', chambre_2: 'Chambre 2', chambre_3: 'Chambre 3',
  chambre_4: 'Chambre 4', chambre_5: 'Chambre 5',
  salle_eau_12: "Salle d'eau (ch. 1 & 2)",
  salle_bain_34: 'Salle de bain (ch. 3 & 4)',
  salle_eau_privee_5: "Salle d'eau privée (ch. 5)",
  wc_partages_12: 'WC partagés (ch. 1 & 2)',
  wc_partages_34: 'WC partagés (ch. 3 & 4)',
  wc_prives_5: 'WC privés (ch. 5)'
};

const ELEM_LABELS = {
  sol: 'Sol', murs: 'Murs', plafond: 'Plafond', fenetres: 'Fenêtres',
  porte_s: 'Porte(s)', eclairage: 'Éclairage', prises_interrupteurs: 'Prises/Interrupteurs',
  projecteur: 'Projecteur', ecran: 'Écran', enceinte: 'Enceinte',
  plaques: 'Plaques', four: 'Four', hotte: 'Hotte', refrigerateur: 'Réfrigérateur',
  congelateur: 'Congélateur', lave_vaisselle: 'Lave-vaisselle', evier: 'Évier',
  machine_1: 'Machine 1', machine_2: 'Machine 2', seche_linge: 'Sèche-linge'
};

function text(content, bold = false) {
  return { type: 'text', text: { content: String(content) }, annotations: bold ? { bold: true } : {} };
}

const blocks = [];

// En-tête résumé
blocks.push({
  type: 'paragraph',
  paragraph: { rich_text: [
    text(`Type : ${meta.type === 'entree' ? 'Entrée' : 'Sortie'}  |  Chambre ${meta.chambre}  |  ${meta.date}`)
  ]}
});

// Une section par pièce
for (const [roomId, room] of Object.entries(pieces)) {
  const roomLabel = ROOM_LABELS[roomId] || roomId;

  blocks.push({
    type: 'heading_2',
    heading_2: { rich_text: [text(roomLabel)] }
  });

  // Tableau 3 colonnes
  const tableRows = [
    {
      type: 'table_row',
      table_row: { cells: [[text('Élément', true)], [text('État', true)], [text('Commentaire', true)]] }
    },
    ...Object.entries(room.elements || {}).map(([elemKey, val]) => ({
      type: 'table_row',
      table_row: { cells: [
        [text(ELEM_LABELS[elemKey] || elemKey)],
        [text(val.etat ? (ETAT_LABELS[val.etat] || val.etat) : '—')],
        [text(val.commentaire || '')]
      ]}
    }))
  ];

  blocks.push({
    type: 'table',
    table: {
      table_width: 3,
      has_column_header: true,
      has_row_header: false,
      children: tableRows
    }
  });

  // Photos (URLs Drive)
  if (room.photoUrls && room.photoUrls.length > 0) {
    for (const url of room.photoUrls) {
      blocks.push({
        type: 'image',
        image: { type: 'external', external: { url } }
      });
    }
  }
}

// Récapitulatif
blocks.push({ type: 'divider', divider: {} });
blocks.push({ type: 'heading_3', heading_3: { rich_text: [text('Récapitulatif')] } });
blocks.push({
  type: 'paragraph',
  paragraph: { rich_text: [text(`Nombre de clés remises : ${cles}`)] }
});
if (observations) {
  blocks.push({
    type: 'paragraph',
    paragraph: { rich_text: [text(`Observations : ${observations}`)] }
  });
}

// Découper en chunks de 100 (limite API Notion)
const chunks = [];
for (let i = 0; i < blocks.length; i += 100) {
  chunks.push(blocks.slice(i, i + 100));
}

return [{ json: { chunks, totalBlocks: blocks.length, meta, locatairePageId: payload._locatairePageId } }];

const pageId = $('Notion - Créer page EDL').first().json.id;
const chunks = $('Code - Construire blocs').first().json.chunks;
const notionKey = $credentials?.notionApi?.apiKey || '';

for (let i = 1; i < chunks.length; i++) {
  await $http.request({
    method: 'PATCH',
    url: `https://api.notion.com/v1/blocks/${pageId}/children`,
    headers: {
      'Authorization': `Bearer ${notionKey}`,
      'Notion-Version': '2022-06-28',
      'Content-Type': 'application/json'
    },
    body: JSON.stringify({ children: chunks[i] })
  });
}

const pageUrl = `https://notion.so/${pageId.replace(/-/g, '')}`;
return [{ json: { pageId, pageUrl } }];

